import { Session } from "@supabase/supabase-js";
import React, { useState, useEffect, useCallback } from "react";
import Sidebar from "./components/Sidebar";
import BottomNav from "./components/BottomNav";
import MainContent from "./components/MainContent";
import type { NavItemId, Profile } from "./types";
import { ToastProvider } from "./hooks/useToast";
import { DataProvider } from "./contexts/DataContext";
import { UIProvider, useUI } from "./contexts/UIContext";
import { SettingsProvider, useSettings } from "./contexts/SettingsContext";
import { supabase } from "./lib/supabase";
import AuthPage from "./components/auth/AuthPage";
import WelcomePage from "./components/auth/WelcomePage";
import { Onboarding } from "./components/Onboarding";
import { LogoIcon } from "./components/Icons";
import SharedReport from "./components/shared/SharedReport";
import SharedReportErrorBoundary from "./src/components/shared/SharedReportErrorBoundary";
import AppUpdateModal from "./components/shared/AppUpdateModal";

import { triggerLightHaptic } from "./lib/haptics";
import { StatusBar, Style } from "@capacitor/status-bar";

import { Capacitor } from "@capacitor/core";
import { App as CapApp } from "@capacitor/app";
import { useToast } from "./hooks/useToast";
import { registerForPushNotifications } from "./lib/notifications";
import { Preferences } from "@capacitor/preferences";
import { getSavedAccounts } from "./lib/accountManager";

import { useData } from "./contexts/DataContext";
import { RealtimeNotificationProvider } from "./contexts/RealtimeNotificationContext";

const NotificationListener: React.FC = () => {
  const { setActiveItem } = useData();
  const { setHighlightedItemId, setStatementAction } = useUI();

  useEffect(() => {
    const handleNotificationInteraction = (e: CustomEvent) => {
      const { route, itemId, parentId } = e.detail;
      if (route) {
        // Ensure valid route by asserting/casting if necessary
        setActiveItem(route as NavItemId);
      }
      if (parentId && setStatementAction) {
        setStatementAction({ route, parentId });
      }
      if (itemId) {
        // Clear any existing highlight first
        setHighlightedItemId(null);

        // Small delay to ensure the DOM has switched to the new route before highlighting
        setTimeout(() => {
          setHighlightedItemId(itemId);

          // Automatically scroll the item into the center of the screen, give statement modals a slightly longer delay to open
          setTimeout(
            () => {
              const target = document.querySelector(".animate-highlight");
              if (target) {
                target.scrollIntoView({ behavior: "smooth", block: "center" });
              }
            },
            parentId ? 500 : 100,
          );
        }, 300);

        // Clear the highlight after 8.5 seconds
        setTimeout(() => setHighlightedItemId(null), 8500);
      }
    };

    window.addEventListener(
      "notificationInteraction",
      handleNotificationInteraction as EventListener,
    );
    return () =>
      window.removeEventListener(
        "notificationInteraction",
        handleNotificationInteraction as EventListener,
      );
  }, [setActiveItem, setHighlightedItemId, setStatementAction]);

  return null;
};


class GlobalErrorBoundary extends React.Component<{children: React.ReactNode}, {hasError: boolean}> {
  constructor(props: any) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  componentDidCatch(error: any, info: any) {
    console.error("Global Error Caught:", error, info);
  }
  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen flex flex-col items-center justify-center bg-neutral-50 dark:bg-neutral-950 p-6">
          <div className="bg-white dark:bg-neutral-900 rounded-3xl p-8 shadow-2xl flex flex-col items-center max-w-sm text-center border border-neutral-100 dark:border-neutral-800">
            <div className="w-16 h-16 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-6">
              <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
            </div>
            <h2 className="text-xl font-bold text-neutral-800 dark:text-neutral-100 mb-2">عذراً، حدث خطأ غير متوقع</h2>
            <p className="text-sm text-neutral-500 mb-8">لقد واجه التطبيق مشكلة غير متوقعة. يرجى إعادة التحميل للمحاولة مرة أخرى.</p>
            <button 
              onClick={() => window.location.reload()}
              className="w-full bg-primary text-white font-bold py-4 rounded-2xl active:scale-95 transition-transform"
            >
              إعادة تحميل التطبيق
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

const AppContent: React.FC<{ profile: Profile }> = ({ profile }) => {
  const [activeItem, setActiveItem] = useState<NavItemId>("dashboard");
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const activeItemRef = React.useRef(activeItem);
  const { settings, loadingSettings } = useSettings();
  const { showToast } = useToast();
  const lastBackPressTime = React.useRef<number>(0);

  useEffect(() => {
    activeItemRef.current = activeItem;
  }, [activeItem]);

  useEffect(() => {
    // Initialize history state on first mount if it's empty to ensure we have a valid base state
    if (!window.history.state || !window.history.state.page) {
      window.history.replaceState(
        { ...window.history.state, page: "dashboard" },
        "",
        window.location.href,
      );
    }

    const handlePopState = (event: PopStateEvent) => {
      if (event.state?.page) {
        setActiveItem(event.state.page);
      } else {
        setActiveItem("dashboard");
      }
    };
    window.addEventListener("popstate", handlePopState);
    return () => window.removeEventListener("popstate", handlePopState);
  }, []);

  const handleNavigation = useCallback(
    (newItemId: NavItemId) => {
      if (newItemId !== activeItem) {
        window.history.pushState({ page: newItemId }, "", window.location.href);
        setActiveItem(newItemId);
      }
    },
    [activeItem],
  );

  useEffect(() => {
    const root = window.document.documentElement;
    if (settings?.accentColor)
      root.setAttribute("data-theme-color", settings.accentColor);
    if (settings?.uiScale) root.setAttribute("data-ui-scale", settings.uiScale);


    // Status bar logic
    if (Capacitor.isNativePlatform()) {
      const isDark = document.documentElement.classList.contains('dark') || window.matchMedia('(prefers-color-scheme: dark)').matches;
      StatusBar.setStyle({ style: isDark ? Style.Dark : Style.Light }).catch(()=> {});
      if (settings?.accentColor) {
        StatusBar.setBackgroundColor({ color: isDark ? '#0a0a0a' : '#ffffff' }).catch(()=> {});
      }
    }

    // Capacitor Hardware Back Button Handling
    let backListener: any;
    const initBackListener = async () => {
      if (Capacitor.isNativePlatform()) {
        backListener = await CapApp.addListener(
          "backButton",

          ({ canGoBack }) => {
            // Check for open modals
            const openModal = document.querySelector('[role="dialog"], .fixed.z-50');
            if (openModal) {
              const closeBtn = openModal.querySelector('button[aria-label="Close"], button[aria-label="إغلاق"], .close-btn') || openModal.querySelector('button');
              if (closeBtn) {
                 closeBtn.click();
              } else {
                 window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }));
              }
              return;
            }

            if (canGoBack) {

              window.history.back();
            } else {
              if (activeItemRef.current === "dashboard") {
                const now = Date.now();
                if (now - lastBackPressTime.current < 2000) {
                  CapApp.exitApp();
                } else {
                  lastBackPressTime.current = now;
                  showToast("اضغط مرة أخرى للخروج من التطبيق", "info");
                }
              } else {
                handleNavigation("dashboard");
              }
            }
          },
        );
      }
    };

    initBackListener();

    // Request Notification Permission and register for push (Android/iOS only)
    const initNotifications = async () => {
      await registerForPushNotifications(profile.id);
    };

    // Initialize immediately to ensure tap listeners catch cached intents, removing the 2s delay
    initNotifications();

    // Session Expiry Listeners (Double Guarantee)
    const handleInactive = () => {
      // Intentionally left empty as we don't clear sessions anymore
    };

    const handleActive = () => {
      // Trigger a silent sync to catch up on any missed websocket events while suspended
      window.dispatchEvent(new CustomEvent("app_resumed"));
    };

    let appStateListener: any;
    if (Capacitor.isNativePlatform()) {
      CapApp.addListener("appStateChange", ({ isActive }) => {
        if (!isActive) handleInactive();
        else handleActive();
      }).then((listener) => {
        appStateListener = listener;
      });
    }

    const handleVisibilityChange = () => {
      if (document.visibilityState === "hidden") {
        handleInactive();
      } else if (document.visibilityState === "visible") {
        handleActive();
      }
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      if (backListener) backListener.remove();
      if (appStateListener) appStateListener.remove();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [settings, handleNavigation, showToast]);

  if (loadingSettings) {
    return (
      <div className="min-h-screen bg-white dark:bg-[#0f172a] flex items-center justify-center pt-[env(safe-area-inset-top)]">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-amber-500 border-t-transparent rounded-full animate-spin"></div>
        </div>
      </div>
    );
  }

  return (
    <UIProvider>
      <DataProvider profile={profile} setActiveItem={handleNavigation}>
        <RealtimeNotificationProvider>
          <NotificationListener />
          <AppUpdateModal />
          <div className="flex h-screen font-sans bg-white dark:bg-[#0f172a] pt-[env(safe-area-inset-top)]">
            <Sidebar
              activeItem={activeItem}
              setActiveItem={handleNavigation}
              isOpen={isSidebarOpen}
              onClose={() => {
                triggerLightHaptic();
                setSidebarOpen(false);
              }}
            />
            <main className="flex-1 overflow-hidden relative pb-[calc(4rem+env(safe-area-inset-bottom))] lg:pb-0">
              <MainContent
                activeItem={activeItem}
                onOpenSidebar={() => {
                  triggerLightHaptic();
                  setSidebarOpen(true);
                }}
              />
            </main>
            <BottomNav activeItem={activeItem} setActiveItem={handleNavigation} />
          </div>
        </RealtimeNotificationProvider>
      </DataProvider>
    </UIProvider>
  );
};

const App: React.FC = () => {
  // Check for shared report route immediately
  const isSharedRoute = window.location.pathname.includes("/shared-report/");
  if (isSharedRoute) {
    return (
      <ToastProvider>
        <SettingsProvider>
          <SharedReportErrorBoundary>
            <SharedReport />
          </SharedReportErrorBoundary>
        </SettingsProvider>
      </ToastProvider>
    );
  }

  const [session, setSession] = useState<Session | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const profileIdRef = React.useRef<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSwitching, setIsSwitching] = useState(false);
  const [isFirstLogin, setIsFirstLogin] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(() => {
    return !localStorage.getItem("onboarding_completed");
  });

  useEffect(() => {
    const handleSwitching = () => setIsSwitching(true);
    window.addEventListener("account_switching", handleSwitching);
    return () =>
      window.removeEventListener("account_switching", handleSwitching);
  }, []);

  const handleLogout = useCallback(async () => {
    localStorage.removeItem("virtual_auth");
    await Preferences.remove({ key: "virtual_auth" });
    await Preferences.set({ key: "was_explicitly_logged_out", value: "true" });
    await supabase.auth.signOut();
    setProfile(null);
    profileIdRef.current = null;
    setSession(null);
  }, []);

  useEffect(() => {
    const initializeAuth = async () => {
      const { value: virtualAuthString } = await Preferences.get({
        key: "virtual_auth",
      });
      if (virtualAuthString) {
        try {
          const virtualProfile = JSON.parse(virtualAuthString);
          if (!virtualProfile || !virtualProfile.id || virtualProfile.id.includes("undefined")) {
            throw new Error("Invalid virtual profile");
          }
          const normalizedProfile = {
            ...virtualProfile,
            id: virtualProfile.id.startsWith("virtual_")
              ? virtualProfile.id
              : `virtual_${virtualProfile.id}`,
            full_name: virtualProfile.full_name,
            role: virtualProfile.role || "viewer",
          } as Profile;

          const accounts = await getSavedAccounts();
          const savedAcc = accounts.find((a) => a.id === normalizedProfile.id);
          if (savedAcc && savedAcc.greenhouseName) {
            normalizedProfile.full_name = savedAcc.greenhouseName;
          }

          setProfile(normalizedProfile);
          setSession({ user: { id: normalizedProfile.id } } as any);
          setLoading(false);
          return true;
        } catch (_err) {
          await Preferences.remove({ key: "virtual_auth" });
          localStorage.removeItem("virtual_auth");
        }
      } else {
        // Check local storage as a fallback, then move it to preferences
        const fallbackStr = localStorage.getItem("virtual_auth");
        if (fallbackStr) {
          try {
            const virtualProfile = JSON.parse(fallbackStr);
            if (!virtualProfile || !virtualProfile.id || virtualProfile.id.includes("undefined")) {
              throw new Error("Invalid virtual profile");
            }
            const normalizedProfile = {
              ...virtualProfile,
              id: virtualProfile.id.startsWith("virtual_")
                ? virtualProfile.id
                : `virtual_${virtualProfile.id}`,
              full_name: virtualProfile.full_name,
              role: virtualProfile.role || "viewer",
            } as Profile;

            const accounts = await getSavedAccounts();
            const savedAcc = accounts.find(
              (a) => a.id === normalizedProfile.id,
            );
            if (savedAcc && savedAcc.greenhouseName) {
              normalizedProfile.full_name = savedAcc.greenhouseName;
            }

            await Preferences.set({ key: "virtual_auth", value: fallbackStr });

            setProfile(normalizedProfile);
            setSession({ user: { id: normalizedProfile.id } } as any);
            setLoading(false);
            return true;
          } catch (_err) {
            localStorage.removeItem("virtual_auth");
          }
        }
      }
      return false;
    };

    const executeAuthCheck = async () => {
      const isVirtual = await initializeAuth();
      if (isVirtual) {
        return; // skip supabase session logic if virtual user
      }

      // Real auth
      try {
        const {
          data: { session },
          error,
        } = await supabase.auth.getSession();
        if (error && !error.message?.toLowerCase().includes("refresh token")) {
          console.error("Session error:", error);
        }

        if (session) {
          await Preferences.remove({ key: "was_explicitly_logged_out" });
          setSession(session);
          fetchProfile(session.user.id);
          return;
        }

        // If no session, try auto-login from saved accounts
        const { value: loggedOut } = await Preferences.get({
          key: "was_explicitly_logged_out",
        });
        if (loggedOut !== "true") {
          const accounts = await getSavedAccounts();
          const { value: lastId } = await Preferences.get({
            key: "last_active_account_id",
          });

          let targetAcc = accounts.find((a) => a.id === lastId);
          if (!targetAcc && accounts.length > 0) targetAcc = accounts[0];

          if (
            targetAcc &&
            !targetAcc.isVirtual &&
            targetAcc.email &&
            targetAcc.password
          ) {
            const { data: signInData, error: signInError } =
              await supabase.auth.signInWithPassword({
                email: targetAcc.email,
                password: targetAcc.password,
              });

            if (signInData.session && !signInError) {
              await Preferences.remove({ key: "was_explicitly_logged_out" });
              setSession(signInData.session);
              fetchProfile(signInData.user.id);
              return;
            }
          } else if (
            targetAcc &&
            targetAcc.isVirtual &&
            targetAcc.username &&
            targetAcc.password
          ) {
            const { data: virtualData, error: virtualError } =
              await supabase.rpc("virtual_login", {
                p_username: targetAcc.username,
                p_password: targetAcc.password,
              });
            const vMember = Array.isArray(virtualData) ? virtualData[0] : virtualData;
            if (vMember && vMember.id && !virtualError) {
              await Preferences.remove({ key: "was_explicitly_logged_out" });
              const virtualUser = {
                id: `virtual_${vMember.id}`,
                full_name: vMember.full_name,
                role: vMember.role,
                parent_id: vMember.owner_id,
                username: vMember.username,
              };
              await Preferences.set({
                key: "virtual_auth",
                value: JSON.stringify(virtualUser),
              });
              localStorage.setItem("virtual_auth", JSON.stringify(virtualUser));
              window.location.reload();
              return;
            }
          }
        }

        setSession(null);
        setLoading(false);
      } catch (err: any) {
        if (
          err &&
          err.message &&
          err.message.toLowerCase().includes("refresh token")
        ) {
          console.warn(
            "Session refresh token not found - user must log in again.",
          );
        } else {
          console.error("Failed to get session:", err);
        }
        setLoading(false);
      }
    };

    executeAuthCheck();
  }, []); // Run only once on mount

  useEffect(() => {
    const setupUserMonitor = (usrProfile: Profile | null) => {
      let channel: any = null;
      if (usrProfile?.id) {
        const currentId = usrProfile.id;
        const isVirtual = currentId.startsWith("virtual_");
        const targetTable = isVirtual ? "virtual_members" : "profiles";
        const rawId = isVirtual ? currentId.replace("virtual_", "") : currentId;

        channel = supabase
          .channel("user-deletion-monitor")
          .on(
            "postgres_changes",
            {
              event: "DELETE",
              schema: "public",
              table: targetTable,
            },
            (payload) => {
              const deletedId = payload.old?.id;
              if (deletedId === rawId) {
                handleLogout();
                window.location.reload();
              }
            },
          )
          .subscribe();
      }
      return channel;
    };

    const monitorChannel = setupUserMonitor(profile);

    return () => {
      if (monitorChannel) supabase.removeChannel(monitorChannel);
    };
  }, [handleLogout, profile?.id]);

  useEffect(() => {
    // مراقبة حالة تسجيل الدخول
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (event, session) => {
      const { value: virtualAuthString } = await Preferences.get({
        key: "virtual_auth",
      });
      if (virtualAuthString) {
        return; // ignore supabase auth changes if virtual
      }
      if (event === "TOKEN_REFRESHED") {
        setSession(session);
        return;
      }
      setSession(session);
      if (session) {
        fetchProfile(session.user.id);
      } else {
        setProfile(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (userId: string) => {
    try {
      if (profileIdRef.current !== userId) {
        setLoading(true); // التأكد من تفعيل حالة التحميل للمستخدم الجديد فقط
      }
      const { data, error } = await supabase
        .from("profiles")
        .select("*")
        .eq("id", userId)
        .single();

      if (error && error.code !== "PGRST116") throw error;

      if (!data) {
        // إنشاء بروفايل إذا كان المستخدم جديداً تماماً
        const { data: newProfile, error: createError } = await supabase
          .from("profiles")
          .insert([
            {
              id: userId,
              full_name: "مستخدم جديد",
              status: "active",
              role: "owner",
            },
          ])
          .select()
          .single();
        if (createError) throw createError;
        setProfile(newProfile);
        profileIdRef.current = userId;
        setIsFirstLogin(true);
      } else {
        const accounts = await getSavedAccounts();
        const savedAcc = accounts.find((a) => a.id === data.id);
        if (savedAcc && savedAcc.greenhouseName) {
          data.full_name = savedAcc.greenhouseName;
        }

        setProfile(data);
        profileIdRef.current = userId;
      }
    } catch (e) {
      console.error("Profile Fetch Error:", e);
      setProfile(null); // التأكد من تصفير البروفايل في حال الخطأ
      profileIdRef.current = null;
    } finally {
      setLoading(false);
    }
  };

  if (loading || isSwitching) {
    return (
      <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-neutral-50 dark:bg-neutral-950 transition-colors duration-300">
        <div className="flex flex-col items-center animate-pulse">
          <div className="relative mb-8">
            <div className="absolute inset-0 bg-primary/20 blur-3xl rounded-full transform scale-150"></div>
            <div className="bg-white dark:bg-neutral-900 p-6 rounded-[2.5rem] shadow-2xl shadow-primary/10 border border-neutral-100 dark:border-neutral-800 relative z-10">
              <LogoIcon className="w-24 h-24 sm:w-32 sm:h-32" />
            </div>
          </div>
          <h1 className="text-3xl sm:text-4xl font-black text-neutral-800 dark:text-neutral-100 tracking-tight mb-2">
            المحاسب الزراعي
          </h1>
          <p className="text-[10px] sm:text-xs font-bold text-neutral-400 dark:text-neutral-500 uppercase tracking-[0.3em]">
            {isSwitching ? "جارٍ تبديل الحساب..." : "جارٍ التحميل..."}
          </p>
        </div>
      </div>
    );
  }

  if (showOnboarding) {
    return <Onboarding onComplete={() => setShowOnboarding(false)} />;
  }

  if (!session) return <AuthPage />;
  if (isFirstLogin && profile)
    return (
      <WelcomePage
        profile={profile}
        onContinue={() => setIsFirstLogin(false)}
      />
    );
  if (!profile) return <AuthPage />;

  return (
    <ToastProvider>
      <SettingsProvider
        userId={profile.parent_id || (profile as any).owner_id || profile.id}
      >
        <GlobalErrorBoundary><AppContent profile={profile} /></GlobalErrorBoundary>
      </SettingsProvider>
    </ToastProvider>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import type { Advance, Person, Cycle } from '../../types';
import { ChevronDownIcon, PlusIcon } from '../Icons';
import { useSettings, terminology } from '../../contexts/SettingsContext';
import { getLocalDateString } from '../../utils/helpers';
import { usePersistedState } from '../../hooks/usePersistedState';
import { triggerSaveHaptic } from '../../lib/haptics';

interface AddAdvanceFormProps {
    onClose?: () => void;
    onSave: (advance: Omit<Advance, 'id' | 'user_id' | 'created_at'> | Advance) => void;
    onCancel: () => void;
    initialData?: Advance | null;
    persons: Person[];
    cycles: Cycle[];
    onManagePersons: () => void;
    newlyAddedPersonId?: string | null;
    onPersonAdded?: () => void;
}

const AddAdvanceForm: React.FC<AddAdvanceFormProps> = ({ onSave, onCancel, initialData, persons, cycles, onManagePersons, newlyAddedPersonId, onPersonAdded }) => {
    const { settings } = useSettings();
    const term = terminology[settings.primaryTerm];
    const activeCycles = useMemo(() => cycles.filter(c => c.status === 'active'), [cycles]);
    const [isSaving, setIsSaving] = useState(false);

    // هل نحن في وضع الإضافة لشخص محدد مسبقاً؟
    // إذا كان هناك person_id ولكن لا يوجد id (أي ليست عملية تعديل)
    const isAddingForSpecificPerson = !!(initialData?.person_id && !initialData?.id);

    // تحديد العروة النشطة الافتراضية بشكل تلقائي
    const defaultCycleId = useMemo(() => {
        if (initialData?.cycle_id) return initialData.cycle_id;
        return activeCycles[0]?.id || '';
    }, [activeCycles, initialData]);

    const [draft, setDraft, clearDraft] = usePersistedState('add_advance_form_draft', {
        personId: initialData?.person_id || '',
        date: getLocalDateString(),
        amount: '',
        cycleId: defaultCycleId,
        reason: '',
        isRepayment: false,
    });

    const [editData, setEditData] = useState({
        personId: initialData?.person_id || '',
        date: initialData?.date || getLocalDateString(),
        amount: (initialData?.amount !== undefined && initialData?.amount !== null) ? String(Math.abs(initialData.amount)) : '',
        cycleId: initialData?.cycle_id || defaultCycleId,
        reason: initialData?.reason || '',
        isRepayment: (initialData?.amount || 0) < 0,
    });

    const formData = initialData?.id ? editData : draft;

    useEffect(() => {
        const today = getLocalDateString();
        if (initialData?.id) {
            setEditData({
                personId: initialData.person_id || '',
                date: initialData.date || today,
                amount: (initialData.amount !== undefined && initialData.amount !== null) ? String(Math.abs(initialData.amount)) : '',
                cycleId: initialData.cycle_id || defaultCycleId,
                reason: initialData.reason || '',
                isRepayment: (initialData.amount || 0) < 0,
            });
        } else {
            if (initialData?.date) {
                setDraft(prev => ({ ...prev, date: initialData.date! }));
            } else if (!draft.date || draft.date < today) {
                setDraft(prev => ({ ...prev, date: today }));
            }
        }
    }, [initialData, defaultCycleId]);

    const setFormData = (updater: any) => {
        if (initialData?.id) {
            setEditData(updater);
        } else {
            setDraft(updater);
        }
    };

    const [errors, setErrors] = useState<Record<string, string>>({});

    const cycleOptions = useMemo(() => {
        const options: Cycle[] = [...activeCycles];
        if (initialData?.cycle_id) {
            const initialCycle = cycles.find(c => c.id === initialData.cycle_id);
            if (initialCycle && !options.some(opt => opt.id === initialCycle.id)) {
                options.unshift(initialCycle);
            }
        }
        return options;
    }, [cycles, activeCycles, initialData]);

    useEffect(() => {
        if (initialData) {
            setFormData({
                personId: initialData.person_id || '',
                date: initialData.date || getLocalDateString(),
                amount: (initialData.amount !== undefined && initialData.amount !== null) ? String(Math.abs(initialData.amount)) : '',
                cycleId: initialData.cycle_id || defaultCycleId,
                reason: initialData.reason || '',
                isRepayment: (initialData.amount || 0) < 0,
            });
        }
    }, [initialData, defaultCycleId]);

    // التأكد من تهيئة السلفة بوضع عروة نشطة إذا كانت الحالية مغلقة أو غير متوفرة لغير التعديل
    useEffect(() => {
        if (!initialData?.id) {
            const activeCyclesList = cycles.filter(c => c.status === 'active');
            const currentSelectedCycle = cycles.find(c => c.id === formData.cycleId);
            if (activeCyclesList.length > 0 && (!currentSelectedCycle || currentSelectedCycle.status !== 'active')) {
                setFormData(prev => ({ ...prev, cycleId: activeCyclesList[0].id }));
            }
        }
    }, [cycles, formData.cycleId, initialData]);

    useEffect(() => {
        if (newlyAddedPersonId && onPersonAdded) {
            setFormData(prev => ({ ...prev, personId: newlyAddedPersonId }));
            onPersonAdded(); 
        }
    }, [newlyAddedPersonId, onPersonAdded]);

    const validate = (): boolean => {
        const newErrors: Record<string, string> = {};
        if (!formData.personId) newErrors.personId = 'يجب اختيار شخص.';
        if (!formData.date) newErrors.date = 'التاريخ مطلوب.';
        const amountNumber = parseFloat(formData.amount);
        if (isNaN(amountNumber) || amountNumber <= 0) newErrors.amount = 'المبلغ يجب أن يكون رقمًا أكبر من صفر.';
        if (!formData.cycleId) newErrors.cycleId = `يجب اختيار ${term.singular}.`;
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;

        if (type === 'checkbox') {
            const checked = (e.target as HTMLInputElement).checked;
            setFormData((prev: any) => ({ ...prev, [name]: checked }));
            return;
        }

        if (name === 'amount') {
            const sanitized = value.replace(/[^0-9.]/g, '');
            const parts = sanitized.split('.');
            const cleanValue = parts.length > 2 ? `${parts[0]}.${parts[1]}` : sanitized;
            setFormData((prev: any) => ({ ...prev, amount: cleanValue }));
        } else {
            setFormData((prev: any) => ({ ...prev, [name]: value }));
        }

        if (errors[name]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[name];
                return newErrors;
            });
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        triggerSaveHaptic();
        if (!validate()) {
            return;
        }
        setIsSaving(true);

        const rawAmount = parseFloat(formData.amount);
        const finalAmount = formData.isRepayment ? -rawAmount : rawAmount;

        const advanceData: Omit<Advance, 'id' | 'user_id' | 'created_at'> = {
            person_id: formData.personId,
            date: formData.date,
            amount: finalAmount,
            cycle_id: formData.cycleId,
            reason: formData.reason || (formData.isRepayment ? 'سداد جزء من السلفة' : '')
        };

        try {
            if (initialData?.id) {
                await onSave({ ...initialData, ...advanceData } as Advance);
            } else {
                await onSave(advanceData);
                clearDraft();
            }
        } catch (error) {
            console.error("Save error:", error);
            setIsSaving(false);
        }
    };

    const inputBaseClasses = "w-full bg-neutral-100 dark:bg-[#182134] border border-neutral-300 dark:border-neutral-700 text-slate-800 dark:text-white rounded-lg p-3 focus:ring-2 focus:ring-primary focus:border-primary transition placeholder:text-neutral-500";
    const labelClasses = "block text-sm font-medium text-gray-500 dark:text-gray-400 mb-2 text-right";

    const ErrorMessage: React.FC<{ error?: string }> = ({ error }) => {
        if (!error) return null;
        return <p className="text-accent-danger text-xs mt-1 text-right">{error}</p>
    };

    return (
        <div className="max-h-[70vh] overflow-y-auto pr-2">
            <form onSubmit={handleSubmit} className="space-y-6">

                <div>
                    <label htmlFor="personId" className={labelClasses}>الشخص المستلف</label>
                    <div className="flex items-center gap-2">
                         <div className="relative flex-grow">
                            <select
                                id="personId"
                                name="personId"
                                value={formData.personId}
                                onChange={handleChange}
                                disabled={isAddingForSpecificPerson}
                                className={`${inputBaseClasses} appearance-none pr-8 ${isAddingForSpecificPerson ? 'opacity-70 cursor-not-allowed bg-neutral-200 dark:bg-neutral-800' : ''} ${errors.personId ? 'border-accent-danger focus:border-accent-danger focus:ring-accent-danger/50' : ''}`}
                            >
                                <option value="" disabled>اختر شخصًا</option>
                                {persons.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                            </select>
                            {!isAddingForSpecificPerson && <ChevronDownIcon className="h-5 w-5 text-gray-400 absolute top-1/2 -translate-y-1/2 left-3 pointer-events-none" />}
                        </div>
                        {!isAddingForSpecificPerson && (
                            <button type="button" onClick={onManagePersons} className="p-3 bg-gray-200 dark:bg-gray-600/50 hover:bg-gray-300 dark:hover:bg-gray-500/50 rounded-lg" aria-label="إدارة الأشخاص">
                                <PlusIcon className="h-6 w-6 text-slate-800 dark:text-white" />
                            </button>
                        )}
                    </div>
                    {isAddingForSpecificPerson && <p className="text-[10px] text-primary font-bold mt-1">يتم الإضافة لهذا الشخص بناءً على اختيارك من القائمة الرئيسية.</p>}
                    <ErrorMessage error={errors.personId} />
                </div>

                <div>
                    <label htmlFor="date" className={labelClasses}>التاريخ</label>
                    <input
                        id="date"
                        name="date"
                        type="date"
                        value={formData.date}
                        onChange={handleChange}
                        className={`${inputBaseClasses} ${errors.date ? 'border-accent-danger focus:border-accent-danger focus:ring-accent-danger/50' : ''}`}
                    />
                    <ErrorMessage error={errors.date} />
                </div>

                <div className="flex items-center gap-3 bg-neutral-100 dark:bg-neutral-800/50 p-3 rounded-lg border border-neutral-200 dark:border-neutral-700/50">
                    <input
                        id="isRepayment"
                        name="isRepayment"
                        type="checkbox"
                        checked={formData.isRepayment}
                        onChange={handleChange}
                        className="w-5 h-5 text-primary border-gray-300 rounded focus:ring-primary"
                    />
                    <label htmlFor="isRepayment" className="text-sm font-bold text-gray-700 dark:text-gray-300 cursor-pointer">
                        تسجيل هذه العملية كسداد مبلغ من السلفة المستحقة 
                    </label>
                </div>

                 <div>
                    <label htmlFor="amount" className={labelClasses}>المبلغ (ج.م)</label>
                    <input
                        id="amount"
                        name="amount"
                        type="text"
                        inputMode="decimal"
                        value={formData.amount}
                        onChange={handleChange}
                        className={`${inputBaseClasses} ${errors.amount ? 'border-accent-danger focus:border-accent-danger focus:ring-accent-danger/50' : ''}`}
                        placeholder="0.00"
                    />
                     <ErrorMessage error={errors.amount} />
                </div>

                <div>
                    <label htmlFor="cycleId" className={labelClasses}>{term.singular}</label>
                    <div className="relative">
                        <select
                            id="cycleId"
                            name="cycleId"
                            value={formData.cycleId}
                            onChange={handleChange}
                            className={`${inputBaseClasses} appearance-none pr-8 ${errors.cycleId ? 'border-accent-danger focus:border-accent-danger focus:ring-accent-danger/50' : ''}`}
                        >
                            <option value="" disabled>اختر {term.singular}</option>
                            {cycleOptions.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                        </select>
                        <ChevronDownIcon className="h-5 w-5 text-gray-400 absolute top-1/2 -translate-y-1/2 left-3 pointer-events-none" />
                    </div>
                    <ErrorMessage error={errors.cycleId} />
                </div>

                <div>
                    <label htmlFor="reason" className={labelClasses}>الوصف/السبب</label>
                    <input
                        id="reason"
                        name="reason"
                        type="text"
                        value={formData.reason}
                        onChange={handleChange}
                        className={inputBaseClasses}
                        placeholder="مثال: سلفة نقدية طارئة"
                    />
                </div>

                <div className="pt-4 flex justify-start gap-4 flex-row-reverse">
                    <button type="submit" onClick={triggerSaveHaptic} disabled={isSaving} className="py-3 px-8 bg-primary text-white font-semibold rounded-lg hover:bg-primary-dark transition shadow-md disabled:bg-primary/50 disabled:cursor-not-allowed">
                        {isSaving ? 'جاري الحفظ...' : (initialData?.id ? 'حفظ التعديلات' : 'حفظ')}
                    </button>
                    <button 
                        type="button" 
                        onClick={() => { clearDraft(); onCancel(); }} 
                        disabled={isSaving}
                        className="py-3 px-8 bg-neutral-200 dark:bg-neutral-700 text-slate-800 dark:text-neutral-100 rounded-lg hover:bg-neutral-300 dark:hover:bg-neutral-600 transition disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        إلغاء
                    </button>
                </div>
            </form>
        </div>
    );
};

