          value={formatCurrency(filteredData.filteredTotalExpenses).replace('EGP', '')}
          icon={TrendingDownIcon}
          trend={trendData.expenses}
          sparklineData={weeklyChartData.expenses}
          color={{
            icon: 'text-accent-danger',
