                                                            </div>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        )}

                                        {/* Deductions Breakdown */}
                                        {selectedTx.raw?.deductions && selectedTx.raw.deductions.length > 0 && (
                                            <div className="border border-neutral-100 dark:border-neutral-800 rounded-2xl p-3.5 bg-rose-50/30 dark:bg-rose-950/20">
