                                className="absolute left-1 top-1/2 -translate-y-1/2 bg-emerald-500 hover:bg-emerald-600 text-white px-2.5 py-1 text-[10px] font-black rounded-md transition-all cursor-pointer shadow-sm"
                            >
                                + حضور جديد
                            </button>
