                                            <span className="font-bold text-rose-600 dark:text-rose-400 tabular-nums" dir="ltr">
                                                -{formatNumber(partner.totalDrawings)} <span dir="rtl" className="text-[10px] text-neutral-400 font-normal">ج.م</span>
                                            </span>
                                        </div>

