import React, { useState } from 'react';
import { supabase } from '../../lib/supabase';
import { useData } from '../../contexts/DataContext';
import { useToast } from '../../hooks/useToast';
import { ShieldIcon, CheckCircleIcon } from '../Icons';

const LinkToOwner: React.FC = () => {
    const { profile } = useData();
    const { showToast } = useToast();
    const [code, setCode] = useState('');
    const [loading, setLoading] = useState(false);

    const handleLink = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!code.trim() || !profile?.id) return;

        setLoading(true);
        try {
            // 1. Find owner by linking code
            // We search for any user with this code (linking_code is unique enough)
            const { data: owner, error: findError } = await supabase
                .from('profiles')
                .select('id, full_name')
                .eq('linking_code', code.trim().toUpperCase())
                .maybeSingle();

            if (findError) throw findError;
            if (!owner) {
                showToast('كود غير صحيح أو منتهي الصلاحية. تأكد من الكود من صاحب الحساب.', 'error');
                setLoading(false);
                return;
            }

            if (owner.id === profile.id) {
                showToast('لا يمكنك ربط حسابك بنفسك.', 'error');
                setLoading(false);
                return;
            }

            // 2. Link this user as viewer
            const { error: updateError } = await supabase
                .from('profiles')
                .update({ 
                    parent_id: owner.id, 
                    role: 'viewer',
                    status: 'active' 
                } as any)
                .eq('id', profile.id);

            if (updateError) {
                console.error('Linking Update Error:', updateError);
                throw updateError;
            }

            showToast(`تم الربط بنجاح بحساب ${owner.full_name}. سيتم تحديث البيانات الآن.`);

            // Reload page to apply changes
            setTimeout(() => window.location.reload(), 1500);
        } catch (_err: any) {
            console.error('Final Link Error:', _err);
            showToast(`فشل في الربط: ${_err.message || 'تأكد من إعدادات Supabase'}`, 'error');
        } finally {
            setLoading(false);
        }
    };

    const handleUnlink = async () => {
        if (!confirm('هل أنت متأكد من فك الارتباط؟ ستفقد القدرة على مشاهدة هذه البيانات.')) return;

        try {
            const { error } = await supabase
                .from('profiles')
                .update({ 
                    parent_id: null, 
                    role: 'user' 
                } as any)
                .eq('id', profile!.id);

            if (error) throw error;
            showToast('تم فك الارتباط بنجاح.');
            setTimeout(() => window.location.reload(), 1000);
        } catch (_err) {
            showToast('فشل في فك الارتباط.', 'error');
        }
    };

    // If linked, show status
    if (profile?.parent_id && profile?.role === 'viewer') {
        return (
            <div className="bg-white dark:bg-neutral-800 rounded-2xl p-6 shadow-soft border border-neutral-100 dark:border-neutral-700">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2.5 bg-green-50 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-xl">
                        <CheckCircleIcon className="w-6 h-6" />
                    </div>
                    <div>
                        <h3 className="text-xl font-bold">حالة الربط</h3>
                        <p className="text-sm text-gray-500">أنت الآن متصل بحساب مالك بصلاحيات "مشاهدة فقط".</p>
                    </div>
                </div>

                <div className="bg-neutral-50 dark:bg-neutral-900/50 p-4 rounded-xl border border-neutral-100 dark:border-neutral-700 mb-6 flex items-center justify-between">
                    <div>
                        <p className="text-xs font-bold text-neutral-400 mb-1">مرتبط بحساب</p>
                        <p className="font-bold">حساب المالك</p>
                    </div>
                    <button 
                        onClick={handleUnlink}
                        className="px-4 py-2 text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg text-xs font-bold transition-all border border-rose-100 dark:border-rose-900/30"
                    >
                        فك الارتباط
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="bg-white dark:bg-neutral-800 rounded-2xl p-6 shadow-soft border border-neutral-100 dark:border-neutral-700">
            <div className="flex items-center gap-3 mb-6">
                <div className="p-2.5 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-xl">
                    <ShieldIcon className="w-6 h-6" />
                </div>
                <div>
                    <h3 className="text-xl font-bold">الربط بحساب مالك</h3>
                    <p className="text-sm text-gray-500">أدخل الكود الذي أرسله لك صاحب الحساب لعرض بياناته.</p>
                </div>
            </div>

            <form onSubmit={handleLink} className="space-y-4">
                <div>
                    <label className="block text-xs font-black text-neutral-400 uppercase tracking-widest mb-2 px-1">كود الربط</label>
                    <input
                        type="text"
                        required
                        placeholder="أدخل الكود هنا (مثال: ZOG-123)..."
                        className="w-full h-14 bg-neutral-100 dark:bg-neutral-900 border-2 border-transparent focus:border-primary/30 rounded-2xl px-6 text-lg font-black tracking-widest text-center focus:ring-4 focus:ring-primary/10 transition-all uppercase"
                        value={code}
                        onChange={(e) => setCode(e.target.value.toUpperCase())}
                    />
                </div>
                <button
                    type="submit"
                    disabled={loading}
                    className="w-full h-14 bg-primary hover:bg-primary-dark text-white rounded-2xl font-black text-sm transition-all shadow-lg shadow-primary/20 active:scale-95 disabled:opacity-50"
                >
                    {loading ? 'جاري التحقق...' : 'تأكيد الربط بالحساب'}
                </button>
            </form>
        </div>
    );
};

export default LinkToOwner;

import React, { useState, useEffect } from 'react';
import { useData } from '../../contexts/DataContext';
import { useUI } from '../../contexts/UIContext';
import { useToast } from '../../hooks/useToast';
import { TrashIcon, UserIcon, ShieldIcon, PlusIcon, LockClosedIcon, FingerPrintIcon } from '../Icons';
import { Copy, Check, AlertTriangle } from 'lucide-react';
import type { VirtualMember } from '../../types';
import { supabase } from '../../lib/supabase';
import { removeSavedAccount } from '../../lib/accountManager';

const TeamSettings: React.FC = () => {
    const { profile } = useData();
    const { presences } = useUI();
    const { showToast } = useToast();
    const [subUsers, setSubUsers] = useState<VirtualMember[]>([]);
    const [loading, setLoading] = useState(false);
    const [fetching, setFetching] = useState(true);
    const [deletingId, setDeletingId] = useState<string | null>(null);
    const [memberToDelete, setMemberToDelete] = useState<VirtualMember | null>(null);
    const [copiedId, setCopiedId] = useState<string | null>(null);

    const [isAdding, setIsAdding] = useState(false);
    const [newMember, setNewMember] = useState({
        full_name: '',
        username: '',
        password: '',
        role: 'viewer' as const
    });

    const fetchSubUsers = async () => {
        if (!profile?.id) return;
        setFetching(true);
        try {
            const { data, error } = await supabase
                .from('virtual_members')
                .select('*')
                .eq('owner_id', profile.id);

            if (error) {
                // Fallback to server API if needed
                const res = await fetch(`/api/auth/list-virtual/${profile.id}`);
                if (res.ok) {
                    const serverMembers = await res.json();
                    setSubUsers(serverMembers);
                    return;
                }
                throw error;
            }
            if (data) setSubUsers(data as any);
        } catch (_err) {
            console.error('Error fetching virtual members:', _err);
        } finally {
            setFetching(false);
        }
    };

    useEffect(() => {
        fetchSubUsers();
    }, [profile?.id]);

    // Listen to real-time changes on virtual_members
    useEffect(() => {
        if (!profile?.id) return;

        const channel = supabase
            .channel('virtual-members-realtime')
            .on(
                'postgres_changes',
                { event: '*', schema: 'public', table: 'virtual_members', filter: `owner_id=eq.${profile.id}` },
                () => {
                    fetchSubUsers();
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [profile?.id]);

    const handleCreateAccount = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!profile?.id) return;
        setLoading(true);

        try {
            const { data, error } = await supabase
                .from('virtual_members')
                .insert([{ 
                    ...newMember, 
                    owner_id: profile.id 
                }])
                .select();

            if (!error && data) {
                showToast('تم إنشاء حساب المطلع بنجاح.');
                setIsAdding(false);
                setNewMember({ full_name: '', username: '', password: '', role: 'viewer' });
                fetchSubUsers();
            } else {
                // Fallback to server endpoint
                const res = await fetch('/api/auth/create-virtual', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ ...newMember, owner_id: profile.id })
                });
                const resData = await res.json();
                if (res.ok && resData?.id) {
                    showToast('تم إنشاء حساب المطلع بنجاح.');
                    setIsAdding(false);
                    setNewMember({ full_name: '', username: '', password: '', role: 'viewer' });
                    fetchSubUsers();
                } else {
                    showToast(resData.error || error?.message || 'فشل في إنشاء الحساب', 'error');
                }
            }
        } catch (_err: any) {
            showToast('خطأ في الاتصال بالخادم', 'error');
        } finally {
            setLoading(false);
        }
    };

    const confirmDeleteMember = async () => {
        if (!memberToDelete) return;
        const id = memberToDelete.id;
        setDeletingId(id);

        try {
            let success = false;
            const { error } = await supabase
                .from('virtual_members')
                .delete()
                .eq('id', id);

            if (!error) {
                success = true;
            } else {
                // Fallback to server API endpoint
                try {
                    const res = await fetch(`/api/auth/delete-virtual/${id}`, {
                        method: 'DELETE'
                    });
                    if (res.ok) success = true;
                } catch {
                    // Fallback failed
                }
            }

            if (success) {
                showToast('تم حذف حساب المطلع بنجاح.');
                setSubUsers(prev => prev.filter(m => m.id !== id));
                // Also remove from saved accounts locally if exists
                await removeSavedAccount(`virtual_${id}`);
                setMemberToDelete(null);
                fetchSubUsers();
            } else {
                showToast('فشل في حذف الحساب. يرجى إعادة المحاولة.', 'error');
            }
        } catch (_err) {
            showToast('فشل في الاتصال بالخادم.', 'error');
        } finally {
            setDeletingId(null);
        }
    };

    const handleCopyInfo = (member: VirtualMember) => {
        const text = `بيانات الدخول إلى التقارير:\nالاسم: ${member.full_name}\nاسم المستخدم: ${member.username}\n(اختر "دخول التقارير" من شاشة تسجيل الدخول)`;
        navigator.clipboard.writeText(text);
        setCopiedId(member.id);
        showToast('تم نسخ بيانات الدخول إلى الحافظة');
        setTimeout(() => setCopiedId(null), 2500);
    };

    if (profile?.role === 'viewer' || profile?.parent_id) return null;

    return (
        <div className="space-y-6">
            {/* Custom Delete Confirmation Modal */}
            {memberToDelete && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in" dir="rtl">
                    <div className="bg-white dark:bg-neutral-800 rounded-3xl p-6 max-w-md w-full shadow-2xl border border-neutral-100 dark:border-neutral-700 animate-scale-up space-y-5">
                        <div className="flex items-center gap-3 text-rose-500">
                            <div className="p-3 bg-rose-50 dark:bg-rose-900/30 rounded-2xl">
                                <AlertTriangle className="w-6 h-6" />
                            </div>
                            <div>
                                <h4 className="text-lg font-black text-neutral-900 dark:text-white">تأكيد حذف حساب المطلع</h4>
                                <p className="text-xs text-neutral-500 dark:text-neutral-400">إجراء لا يمكن التراجع عنه</p>
                            </div>
                        </div>

                        <div className="bg-neutral-50 dark:bg-neutral-900/60 p-4 rounded-2xl border border-neutral-100 dark:border-neutral-700/60 space-y-2">
                            <div className="flex items-center justify-between">
                                <span className="text-xs text-neutral-500">اسم المطلع:</span>
                                <span className="text-sm font-bold text-neutral-900 dark:text-white">{memberToDelete.full_name}</span>
                            </div>
                            <div className="flex items-center justify-between">
                                <span className="text-xs text-neutral-500">اسم المستخدم:</span>
                                <span className="text-xs font-mono font-bold bg-neutral-200 dark:bg-neutral-800 px-2 py-0.5 rounded text-primary">@{memberToDelete.username}</span>
                            </div>
                        </div>

                        <p className="text-xs text-neutral-600 dark:text-neutral-300 leading-relaxed font-medium">
                            هل أنت متأكد من حذف هذا الحساب نهائياً؟ سيفقد هذا المستخدم إمكانية الدخول ومشاهدة تقارير وبيانات المزرعة على الفور.
                        </p>

                        <div className="flex items-center justify-end gap-3 pt-2">
                            <button
                                type="button"
                                onClick={() => setMemberToDelete(null)}
                                disabled={!!deletingId}
                                className="px-5 py-2.5 rounded-xl text-xs font-bold text-neutral-600 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-all"
                            >
                                إلغاء
                            </button>
                            <button
                                type="button"
                                onClick={confirmDeleteMember}
                                disabled={!!deletingId}
                                className="px-5 py-2.5 bg-rose-500 hover:bg-rose-600 text-white rounded-xl text-xs font-black transition-all shadow-lg shadow-rose-500/20 active:scale-95 disabled:opacity-50 flex items-center gap-2"
                            >
                                {deletingId ? (
                                    <>
                                        <svg className="animate-spin h-4 w-4 text-white" fill="none" viewBox="0 0 24 24">
                                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path>
                                        </svg>
                                        <span>جاري الحذف...</span>
                                    </>
                                ) : (
                                    <>
                                        <TrashIcon className="w-4 h-4" />
                                        <span>تأكيد الحذف</span>
                                    </>
                                )}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <div className="bg-white dark:bg-neutral-800 rounded-2xl p-6 shadow-soft border border-neutral-100 dark:border-neutral-700">
                <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-xl">
                            <ShieldIcon className="w-6 h-6" />
                        </div>
                        <div>
                            <h3 className="text-xl font-bold text-neutral-800 dark:text-neutral-50">صلاحيات الوصول والتقارير</h3>
                            <p className="text-sm text-neutral-500">أنشئ حسابات دخول لتمكين الشركاء أو المستثمرين من متابعة التقارير والبيانات.</p>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        <button 
