                  d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6"
                />
              </svg>
              <span className="text-[11px] font-bold text-emerald-700 dark:text-emerald-400">
                الأعلى سعراً: {maxPriceObj["سعر السوق"]} ج{" "}
                <span className="opacity-70 font-normal">
