    const [isDiscountModalOpen, setDiscountModalOpen] = useState(false);
    const [isStatementModalOpen, setStatementModalOpen] = useState(false);
    const [selectedSupplierId, setSelectedSupplierId] = useState<string | null>(null);
    const [editingPaymentId, setEditingPaymentId] = useState<string | null>(null);
    const [editingDiscountId, setEditingDiscountId] = useState<string | null>(null);
    const [editingSupplierId, setEditingSupplierId] = useState<string | null>(null);
    const [addingPaymentForSupplierId, setAddingPaymentForSupplierId] = useState<string | null>(null);
    const [addingDiscountForSupplierId, setAddingDiscountForSupplierId] = useState<string | null>(null);
    const [paymentToDelete, setPaymentToDelete] = useState<string | null>(null);
    const [supplierToDelete, setSupplierToDelete] = useState<string | null>(null);
    const [discountToDelete, setDiscountToDelete] = useState<string | null>(null);
    const [isDeletingSupplier, setIsDeletingSupplier] = useState(false);
    const [isDeletingPayment, setIsDeletingPayment] = useState(false);
    const [isDeletingDiscount, setIsDeletingDiscount] = useState(false);

    const handleAddDiscountForSupplier = (supplierId: string) => {
        setEditingDiscountId(null);
        setAddingDiscountForSupplierId(supplierId);
        setDiscountModalOpen(true);
    };

    const handleStartEditDiscount = (expenseId: string) => {
        setEditingDiscountId(expenseId);
        setAddingDiscountForSupplierId(null);
        setStatementModalOpen(false);
        setTimeout(() => {
            setDiscountModalOpen(true);
        }, 150);
    };

    const handleDeleteDiscountRequest = (expenseId: string) => {
        setDiscountToDelete(expenseId);
    };

    const confirmDeleteDiscount = async () => {
        if (discountToDelete) {
            setIsDeletingDiscount(true);
            try {
                await deleteExpense(discountToDelete);
                showToast('تم حذف الخصم المكتسب وتحديث الدورة المحاسبية والأرباح بنجاح.');
                setDiscountToDelete(null);
            } catch (error: any) {
                console.error(error);
                showToast(error.message || 'حدث خطأ أثناء حذف الخصم.', 'error');
            } finally {
                setIsDeletingDiscount(false);
            }
        }
    };

    const handleSaveDiscount = async (discountData: Omit<Expense, 'id' | 'user_id' | 'created_at'>) => {
        try {
            if (editingDiscountId) {
                await updateExpense({ ...discountData, id: editingDiscountId } as Expense);
                showToast('تم تحديث الخصم بنجاح.');
            } else {
                await addExpense(discountData);
                showToast('تم تسجيل الخصم وتحديث المصروفات والأرباح بنجاح.');
            }
            setDiscountModalOpen(false);
            setAddingDiscountForSupplierId(null);
            setEditingDiscountId(null);
        } catch (error: any) {
            console.error(error);
            showToast(error.message || 'حدث خطأ أثناء حفظ الخصم.', 'error');
            throw error;
        }
    };

    const editingDiscount = useMemo(() => {
        if (editingDiscountId) {
            return rawExpenses.find(e => e.id === editingDiscountId) || null;
        }
        return null;
    }, [editingDiscountId, rawExpenses]);

    const editingSupplier = useMemo(() => {
        return suppliers.find(s => s.id === editingSupplierId) || null;
    }, [editingSupplierId, suppliers]);

    const editingPayment = useMemo(() => {
        if (editingPaymentId) {
            return supplierPayments.find(p => p.id === editingPaymentId) || null;
        } else if (addingPaymentForSupplierId) {
            return { supplier_id: addingPaymentForSupplierId } as unknown as SupplierPayment;
        }
        return null;
    }, [editingPaymentId, addingPaymentForSupplierId, supplierPayments]);

    useEffect(() => {
        if (statementAction?.route === 'suppliers' && statementAction.parentId) {
            setSelectedSupplierId(statementAction.parentId);
            setStatementModalOpen(true);
            setStatementAction(null);
        }
    }, [statementAction, setStatementAction]);

    const handleSaveSupplier = async (name: string, openingBalance?: number) => {
        try {
            if (editingSupplierId) {
                await updateSupplier({ ...editingSupplier!, name, opening_balance: openingBalance });
                showToast('تم تحديث المورد بنجاح.');
            } else {
                await addSupplier(name, openingBalance);
                showToast('تم إضافة المورد بنجاح.');
            }
            setSupplierModalOpen(false);
            setEditingSupplierId(null);
        } catch (error: any) {
            showToast(error.message || 'حدث خطأ أثناء حفظ المورد.', 'error');
            throw error;
        }
    };

    const handleDeleteRequest = (id: string) => {
        setSupplierToDelete(id);
    };

    const confirmDeleteSupplier = async () => {
        if (supplierToDelete) {
            setIsDeletingSupplier(true);
            try {
                const success = await deleteSupplier(supplierToDelete);
                if (success) {
                    showToast('تم حذف المورد بنجاح.', 'success');
                    setSupplierToDelete(null);
                }
            } catch (e: any) {
                showToast(e.message || 'فشل حذف المورد.', 'error');
            } finally {
                setIsDeletingSupplier(false);
            }
        }
    };

    const handleSavePayment = async (payment: Omit<SupplierPayment, 'id' | 'user_id' | 'created_at'> | SupplierPayment) => {
        try {
            if ('id' in payment && payment.id) {
                await updateSupplierPayment(payment as SupplierPayment);
                showToast('تم تحديث الدفعة بنجاح.');
            } else {
                await addSupplierPayment(payment);
                showToast('تم إضافة الدفعة بنجاح.');
            }
            setPaymentModalOpen(false);
            setEditingPaymentId(null);
            setAddingPaymentForSupplierId(null);
        } catch (error: any) {
            console.error(error);
            showToast(error.message || 'حدث خطأ أثناء حفظ الدفعة.', 'error');
            throw error;
        }
    };

    const handleViewStatement = (supplierId: string) => {
        setSelectedSupplierId(supplierId);
        setStatementModalOpen(true);
    };

    const closeStatement = useCallback(() => {
        setStatementModalOpen(false);
        setSelectedSupplierId(null);
    }, []);

    const handleAddPaymentForSupplier = (supplierId: string) => {
        setEditingPaymentId(null);
        setAddingPaymentForSupplierId(supplierId);
        setPaymentModalOpen(true);
    };

    const handleStartEditPayment = (payment: SupplierPayment) => {
        setEditingPaymentId(payment.id);
        setAddingPaymentForSupplierId(null);
        setStatementModalOpen(false);
        setTimeout(() => {
            setPaymentModalOpen(true);
        }, 150);
    };

    const handleDeletePaymentRequest = (id: string) => {
        setPaymentToDelete(id);
    };

    const confirmDeletePayment = async () => {
        if (paymentToDelete) {
            setIsDeletingPayment(true);
            try {
                await deleteSupplierPayment(paymentToDelete);
                showToast('تم حذف الدفعة بنجاح.');
                setPaymentToDelete(null);
            } catch (e: any) {
                showToast(e.message || 'فشل حذف الدفعة.', 'error');
            } finally {
                setIsDeletingPayment(false);
            }
        }
    };

    const handleCancelPaymentForm = () => {
        setPaymentModalOpen(false);
        setEditingPaymentId(null);
        setAddingPaymentForSupplierId(null);
        if (selectedSupplierId) {
             setTimeout(() => {
                setStatementModalOpen(true);
             }, 150);
        }
    }

    return (
        <>
            <Modal
                isOpen={!!supplierToDelete}
                onClose={() => setSupplierToDelete(null)}
                title="تأكيد حذف المورد"
            >
                <p className="text-neutral-500 dark:text-neutral-400">هل أنت متأكد من رغبتك في حذف هذا المورد؟ لا يمكن التراجع عن هذا الإجراء.</p>
                <div className="mt-6 flex justify-start gap-4 flex-row-reverse">
                    <button 
                        onClick={confirmDeleteSupplier} 
                        disabled={isDeletingSupplier}
                        className="rounded-lg bg-accent-danger px-4 py-2 text-white font-bold disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {isDeletingSupplier ? 'جاري الحذف...' : 'حذف'}
                    </button>
                    <button 
                        onClick={() => setSupplierToDelete(null)} 
                        disabled={isDeletingSupplier}
                        className="rounded-lg bg-neutral-200 dark:bg-neutral-700 px-4 py-2 font-bold disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        إلغاء
                    </button>
                </div>
            </Modal>
            <Modal
                isOpen={isSupplierModalOpen}
                onClose={() => { setSupplierModalOpen(false); setEditingSupplierId(null); }}
                title={editingSupplier ? "تعديل مورد" : "إضافة مورد جديد"}
            >
                <AddSupplierForm 
                    onSave={handleSaveSupplier}
                    onCancel={() => { setSupplierModalOpen(false); setEditingSupplierId(null); }}
                    initialName={editingSupplier?.name}
                    initialOpeningBalance={editingSupplier?.opening_balance}
                />
            </Modal>

            <Modal
                isOpen={isPaymentModalOpen}
                onClose={handleCancelPaymentForm}
                title={editingPayment?.id ? 'تعديل دفعة' : 'إضافة دفعة مورد'}
                size="lg"
            >
                <AddPaymentForm
                    onSave={handleSavePayment}
                    onCancel={handleCancelPaymentForm}
                    suppliers={suppliers}
                    cycles={cycles}
                    initialData={editingPayment}
                />
            </Modal>

            <Modal
                isOpen={isDiscountModalOpen}
                onClose={() => { setDiscountModalOpen(false); setAddingDiscountForSupplierId(null); setEditingDiscountId(null); }}
                title={editingDiscount ? "تعديل خصم مورد" : "تسجيل خصم ممنوح من المورد"}
                size="lg"
            >
                {(addingDiscountForSupplierId || editingDiscountId) && (
                    <AddDiscountForm
                        onSave={handleSaveDiscount}
                        onCancel={() => { 
                            setDiscountModalOpen(false); 
                            setAddingDiscountForSupplierId(null); 
                            setEditingDiscountId(null);
                            if (selectedSupplierId) {
                                setTimeout(() => setStatementModalOpen(true), 150);
                            }
                        }}
                        supplierId={addingDiscountForSupplierId || editingDiscount?.supplier_id || ''}
                        suppliers={suppliers}
                        cycles={cycles}
                        initialData={editingDiscount}
                    />
                )}
            </Modal>

            <Modal
                isOpen={isStatementModalOpen}
                onClose={() => {
                    closeStatement();
                }}
                title={`كشف الحساب: ${suppliers.find(s => s.id === selectedSupplierId)?.name || ''}`}
                size="3xl"
            >
                {selectedSupplierId && (
                    <SupplierStatement 
                        supplierId={selectedSupplierId} 
                        onEdit={isViewer ? undefined as any : handleStartEditPayment}
                        onDelete={isViewer ? undefined as any : handleDeletePaymentRequest}
                        onEditDiscount={isViewer ? undefined as any : handleStartEditDiscount}
                        onDeleteDiscount={isViewer ? undefined as any : handleDeleteDiscountRequest}
                    />
                )}
            </Modal>

            <Modal
                isOpen={!!paymentToDelete}
                onClose={() => setPaymentToDelete(null)}
                title="تأكيد حذف الدفعة"
            >
                <p className="text-neutral-500 dark:text-neutral-400">هل أنت متأكد من رغبتك في حذف هذه الدفعة المالية؟</p>
                <div className="mt-6 flex justify-start gap-4 flex-row-reverse">
                    <button 
                        onClick={confirmDeletePayment} 
                        disabled={isDeletingPayment}
                        className="rounded-lg bg-accent-danger px-4 py-2 text-white font-bold disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {isDeletingPayment ? 'جاري الحذف...' : 'حذف'}
                    </button>
                    <button 
                        onClick={() => setPaymentToDelete(null)} 
                        disabled={isDeletingPayment}
                        className="rounded-lg bg-neutral-200 dark:bg-neutral-700 px-4 py-2 font-bold disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        إلغاء
                    </button>
                </div>
            </Modal>

            <Modal
                isOpen={!!discountToDelete}
                onClose={() => setDiscountToDelete(null)}
                title="تأكيد حذف الخصم المكتسب"
            >
                <div className="text-right space-y-4 font-sans" dir="rtl">
                    <p className="text-sm font-semibold text-neutral-600 dark:text-neutral-400 leading-relaxed">
                        هل أنت متأكد من رغبتك في حذف هذا الخصم الممنوح من المورد؟
                    </p>
                    <div className="p-3.5 bg-rose-50 dark:bg-rose-950/20 border border-rose-100 dark:border-rose-900/30 rounded-2xl text-rose-750 dark:text-rose-300 text-xs leading-relaxed font-bold">
                        ⚠️ تنبيه مالي: حذف هذا الخصم سيؤدي إلى إعادة مديونية المورد لسابقتها (زيادة مطلوباتك)، وفي نفس الوقت سيقوم بزيادة مصروفات عروة الزراعة مما يخفض من صافي الأرباح تلقائياً.
                    </div>
                </div>
                <div className="mt-6 flex justify-start gap-4 flex-row-reverse">
                    <button 
                        onClick={confirmDeleteDiscount} 
                        disabled={isDeletingDiscount}
                        className="rounded-lg bg-accent-danger hover:bg-rose-650 px-5 py-2 text-white text-xs font-black disabled:opacity-50 disabled:cursor-not-allowed active:scale-95 transition-all"
                    >
                        {isDeletingDiscount ? 'جاري الحذف...' : 'نعم، احذف الخصم'}
                    </button>
                    <button 
                        onClick={() => setDiscountToDelete(null)} 
                        disabled={isDeletingDiscount}
                        className="rounded-lg bg-neutral-200 dark:bg-neutral-800 text-neutral-800 dark:text-white px-5 py-2 text-xs font-bold disabled:opacity-50 disabled:cursor-not-allowed active:scale-95 transition-all"
                    >
                        إلغاء
                    </button>
                </div>
            </Modal>


            <SuppliersListView 
                onAddSupplier={() => setSupplierModalOpen(true)} 
                onEditSupplier={(supplier) => { setEditingSupplierId(supplier.id); setSupplierModalOpen(true); }}
                onAddPaymentForSupplier={handleAddPaymentForSupplier}
                onAddDiscountForSupplier={handleAddDiscountForSupplier}
                onViewStatement={handleViewStatement}
                onDeleteRequest={handleDeleteRequest}
            />
        </>
    );
};

export default SupplierManager;

import React, { useMemo, useState } from 'react';
import { useData } from '../../contexts/DataContext';
import { formatCurrency } from '../../utils/helpers';
import type { SupplierPayment } from '../../types';
import { PencilIcon, TrashIcon, LucideTag } from '../Icons';

interface SupplierStatementProps {
    supplierId: string;
    onEdit: (payment: SupplierPayment) => void;
    onDelete: (id: string) => void;
    onEditDiscount: (expenseId: string) => void;
    onDeleteDiscount: (expenseId: string) => void;
}

const SupplierStatement: React.FC<SupplierStatementProps> = ({ supplierId, onEdit, onDelete, onEditDiscount, onDeleteDiscount }) => {
    const { suppliers, rawExpenses: expenses, supplierPayments, highlightedItemId, isPhase2Loading, cycles } = useData();

    // Search, Filter, Sort, Copy states
    const [searchQuery, setSearchQuery] = useState('');
    const [filterType, setFilterType] = useState<'all' | 'expense' | 'payment'>('all');
    const [sortOrder, setSortOrder] = useState<'desc' | 'asc'>('desc');
    const [copied, setCopied] = useState(false);

    const supplier = useMemo(() => suppliers.find(s => s.id === supplierId), [suppliers, supplierId]);
    const cycleMap = useMemo(() => new Map(cycles.map(c => [c.id, c.name])), [cycles]);



    const transactions = useMemo(() => {
        if (!supplierId) return [];

        const supplierExpenses = expenses
            .filter(e => e.supplier_id === supplierId && e.payment_method === 'credit')
            .map(e => ({
                id: `exp-${e.id}`,
                originalId: e.id,
                type: 'expense' as const,
                date: e.date,
                description: e.description || 'فاتورة مشتريات',
                debit: e.amount || 0,
                credit: 0,
                cycleId: e.cycle_id,
                isDiscount: e.isDiscount || false,
                is_establishment: e.is_establishment || false,
            }));

        const payments = supplierPayments
            .filter(p => p.supplier_id === supplierId)
            .map(p => ({
                ...p,
                originalId: p.id,
                type: 'payment' as const,
                debit: 0,
                credit: p.amount || 0,
                cycleId: p.cycle_id,
            }));

        // Sort Chronologically (Oldest to Newest) for correct balance calculation
        return [...supplierExpenses, ...payments].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    }, [supplierId, expenses, supplierPayments]);

    const openingBalance = supplier?.opening_balance || 0;

    // Add running balance and cycle names
    const transactionsWithBalance = useMemo(() => {
        let runningBalance = openingBalance;
        return transactions.map(tx => {
            runningBalance += tx.debit - tx.credit;
            return { 
                ...tx, 
                balance: runningBalance,
                cycleName: tx.cycleId ? cycleMap.get(tx.cycleId) : undefined
            };
        });
    }, [transactions, openingBalance, cycleMap]);

    // Apply interactive search and type filtering
    const filteredTransactions = useMemo(() => {
        return transactionsWithBalance.filter(tx => {
            // Type Filter
            if (filterType !== 'all' && tx.type !== filterType) return false;

            // Search query filter
            if (searchQuery.trim() !== '') {
                const query = searchQuery.toLowerCase();
                const descMatch = (tx.description || '').toLowerCase().includes(query);
                const cycleMatch = (tx.cycleName || '').toLowerCase().includes(query);
                const amountMatch = String(tx.debit || tx.credit || '').includes(query);
                const dateMatch = tx.date.includes(query);
                return descMatch || cycleMatch || amountMatch || dateMatch;
            }

            return true;
        });
    }, [transactionsWithBalance, filterType, searchQuery]);

    // Apply Sorting Toggle
    const displayTransactions = useMemo(() => {
        const sorted = [...filteredTransactions];
        if (sortOrder === 'desc') {
            return sorted.reverse(); // Newest first
        }
        return sorted; // Oldest first
    }, [filteredTransactions, sortOrder]);

    const finalBalance = transactionsWithBalance.length > 0 
        ? transactionsWithBalance[transactionsWithBalance.length - 1].balance 
        : openingBalance;

    const totalDebit = transactions.reduce((sum, tx) => sum + tx.debit, 0) + openingBalance;
    const totalCredit = transactions.reduce((sum, tx) => sum + tx.credit, 0);

    // Format Statement text for sharing/WhatsApp
    const handleCopyStatement = () => {
        if (!supplier) return;
        const dateStr = new Date().toLocaleDateString('ar-EG', { year: 'numeric', month: 'long', day: 'numeric' });

        let text = `📄 *كشف حساب المورد: ${supplier.name}*\n`;
        text += `📅 تاريخ الاستخراج: ${dateStr}\n`;
        text += `----------------------------------------\n`;
        text += `💵 رصيد افتتاحي: ${formatCurrency(openingBalance)}\n`;
        text += `📈 إجمالي المشتريات (عليه): ${formatCurrency(totalDebit)}\n`;
        text += `📉 إجمالي المسدد (له): ${formatCurrency(totalCredit)}\n`;
        text += `----------------------------------------\n`;
        text += `🔴 *الرصيد المتبقي المستحق: ${formatCurrency(finalBalance)}*\n`;
        text += `========================================\n\n`;
        text += `📋 *آخر المعاملات المسجلة:*\n`;

        displayTransactions.slice(0, 10).forEach((tx) => {
            const isExp = tx.type === 'expense';
            const typeText = isExp ? '📥 مشتريات' : '📤 سداد';
            const val = isExp ? tx.debit : tx.credit;
            const cycleText = tx.cycleName ? ` [العروة: ${tx.cycleName}]` : '';
            text += `• ${tx.date} - ${tx.description}${cycleText}\n  👈 القيمة: ${formatCurrency(val)} | (${typeText}) | الرصيد: ${formatCurrency(tx.balance)}\n`;
        });

        if (displayTransactions.length > 10) {
            text += `• ... ومتبقي حركات أخرى.\n`;
        }

        navigator.clipboard.writeText(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    if (!supplier) {
        if (isPhase2Loading) {
            return (
                <div className="p-12 text-center space-y-4">
                    <div className="w-12 h-12 border-4 border-primary/20 border-t-primary rounded-full animate-spin mx-auto"></div>
                    <p className="text-neutral-500 font-bold">جاري تحضير بيانات المورد...</p>
                </div>
            );
        }
        return <div className="p-4 text-center">لم يتم العثور على المورد.</div>;
    }

    return (
        <div className="max-h-[75vh] overflow-y-auto pr-2 -mr-2 text-right font-sans">
            <div className="space-y-6 p-1">
                {/* Compact, Overhauled Remaining Balance Card with Total Purchases & Payments Integrated */}
                <div className="space-y-3">
                    {/* Compact King Card: Outstanding Balance to Pay with internal sub-metrics */}
                    <div className="bg-gradient-to-br from-neutral-900 via-slate-900 to-indigo-950 text-white rounded-xl p-3 sm:p-4 border border-slate-800 shadow-md relative overflow-hidden group transition-all duration-300">
                        {/* Elegant background highlight glow */}
                        <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-550/5 rounded-full blur-[40px] pointer-events-none group-hover:bg-emerald-550/10 transition-all duration-500" />

                        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 relative z-10">
                            <div>
                                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-black tracking-wider text-emerald-400 bg-emerald-500/10 border border-emerald-500/20 shadow-xs mb-1">
                                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
                                    المطلوب سداده للمورد (الرصيد المتبقي)
                                </span>

                                <div className="flex items-baseline gap-0.5 mt-0.5">
                                    <p className="font-extrabold text-xl sm:text-2xl tracking-tight tabular-nums truncate text-emerald-400 drop-shadow-sm">
                                        {formatCurrency(finalBalance)}
                                    </p>
                                    <span className="text-[10px] font-bold text-neutral-400 mr-1">ج.م</span>
                                </div>
                            </div>

                            <div className="flex flex-col sm:items-end justify-center">
                                <span className="text-[9px] text-neutral-450 font-medium">اسم المورد</span>
                                <span className="text-xs sm:text-sm font-extrabold text-white">{supplier.name}</span>
                                {supplier.phone && (
                                    <span className="text-[8px] text-neutral-500 font-mono" dir="ltr">{supplier.phone}</span>
                                )}
                            </div>
                        </div>

                        {/* Internal Sub-metrics in footer: Total Purchases and Total Paid */}
                        <div className="mt-2.5 pt-2 border-t border-white/10 grid grid-cols-2 gap-3 text-right relative z-10">
                            <div>
                                <span className="text-[9px] text-slate-400 block font-bold mb-0.5">إجمالي المشتريات (عليه)</span>
                                <div className="flex items-baseline gap-1">
                                    <span className="text-xs sm:text-sm font-extrabold text-rose-450 tabular-nums">
                                        {formatCurrency(totalDebit)}
                                    </span>
                                    <span className="text-[8px] text-slate-450 font-bold mr-0.5">ج.م</span>
                                </div>
                            </div>
                            <div className="border-r border-white/10 pr-3">
                                <span className="text-[9px] text-slate-400 block font-bold mb-0.5">إجمالي المسدد (له)</span>
                                <div className="flex items-baseline gap-1">
                                    <span className="text-xs sm:text-sm font-extrabold text-emerald-400 tabular-nums">
                                        {formatCurrency(totalCredit)}
                                    </span>
                                    <span className="text-[8px] text-slate-450 font-bold mr-0.5">ج.م</span>
                                </div>
                            </div>
                        </div>

                        {/* Subtle Transaction/Account Info Bar */}
                        <div className="mt-2 pt-1.5 border-t border-white/5 flex items-center justify-between text-[8px] sm:text-[9px] text-slate-500 font-medium relative z-10">
                            <span>مجموع العمليات: {transactions.length} معاملة</span>
                            <span>الرصيد الافتتاحي: {formatCurrency(openingBalance)} ج.م</span>
                        </div>
