                    {/* Fintech Filter Tabs */}
                    <div className="flex items-center p-1 bg-neutral-100 dark:bg-neutral-800/80 rounded-2xl border border-neutral-200/50 dark:border-neutral-700/50 self-stretch sm:self-auto">
