                    }`}>
                        <div className="flex items-center gap-1.5">
                            {historyTab === 'inflow' ? <TrendingUpIcon className="w-4 h-4 text-emerald-600" /> : <TrendingDownIcon className="w-4 h-4 text-rose-600" />}
