                                            <div className="flex items-center gap-2 flex-wrap">
                                                <p className="text-xs sm:text-sm font-black text-neutral-900 dark:text-white truncate max-w-[160px] sm:max-w-[280px]">
                                                    {h.note}
                                                </p>
                                                {isEditableFunding && (
