interface SettingsContextType {
  settings: AppSettings;
  updateSettings: (newSettings: Partial<AppSettings>) => void;
  loadingSettings: boolean;
}

const SettingsContext = createContext<SettingsContextType | undefined>(
  undefined,
);

export const SettingsProvider: React.FC<{
  children: ReactNode;
  userId?: string;
}> = ({ children, userId }) => {
  const getStorageKey = (uid?: string) => uid ? `local-app-settings_${uid}` : "local-app-settings_anon";

  const [settings, setSettings] = useState<AppSettings>(() => {
    const key = getStorageKey(userId);
    const saved = localStorage.getItem(key);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        const merged = { ...defaultSettings, ...parsed };
        if (parsed.systems) {
          merged.systems = { ...defaultSettings.systems, ...parsed.systems };
        }
        return merged;
      } catch (e) {
        console.error("Error parsing initial local settings:", e);
      }
    }
    return defaultSettings;
  });
  const [loadingSettings, setLoadingSettings] = useState(true);

  // 1. تحميل الإعدادات عند تغير المستخدم
  useEffect(() => {
    let isCancelled = false;

    const loadSettings = async () => {
      const storageKey = getStorageKey(userId);
      setLoadingSettings(true);

      if (!userId || userId.includes("undefined")) {
        const saved = localStorage.getItem(storageKey);
        if (saved) {
          try {
            const parsed = JSON.parse(saved);
            const merged = { ...defaultSettings, ...parsed };
            if (parsed.systems) {
              merged.systems = {
                ...defaultSettings.systems,
                ...parsed.systems,
              };
            }
            if (!isCancelled) setSettings(merged);
          } catch (e) {
            console.error("Error parsing local settings:", e);
          }
        } else {
          if (!isCancelled) setSettings(defaultSettings);
        }
        if (!isCancelled) setLoadingSettings(false);
        return;
      }

      try {
        const { data, error } = await supabase
          .from("profiles")
          .select("app_settings")
          .eq("id", userId)
          .single();

        if (error) throw error;

        if (data?.app_settings) {
          const parsed = data.app_settings as any;
          const finalSettings = { ...defaultSettings, ...parsed };
          if (parsed.systems) {
            finalSettings.systems = { ...defaultSettings.systems, ...parsed.systems };
          }
          if (!isCancelled) {
            setSettings(finalSettings as AppSettings);
            localStorage.setItem(storageKey, JSON.stringify(finalSettings));
          }
        } else {
          // إذا لم تكن هناك إعدادات في قاعدة البيانات، نستخدم التخزين المحلي لهذا الحساب أو الافتراضي
          const saved = localStorage.getItem(storageKey);
          let initial = defaultSettings;
          if (saved) {
            try {
              const parsed = JSON.parse(saved);
              initial = { ...defaultSettings, ...parsed };
              if (parsed.systems) {
                initial.systems = {
                  ...defaultSettings.systems,
                  ...parsed.systems,
                };
              }
            } catch (e) {
              console.error(e);
            }
          }
          if (!isCancelled) {
            setSettings(initial);
            localStorage.setItem(storageKey, JSON.stringify(initial));
          }
          // حفظها في قاعدة البيانات لأول مرة
          await supabase
            .from("profiles")
            .update({ app_settings: initial })
            .eq("id", userId);
        }
      } catch (e) {
        console.error("Error loading settings from Supabase:", e);
        // Fallback to local storage for this specific user
        const saved = localStorage.getItem(storageKey);
        if (saved && !isCancelled) {
          try {
            const parsed = JSON.parse(saved);
            const merged = { ...defaultSettings, ...parsed };
            if (parsed.systems) {
              merged.systems = { ...defaultSettings.systems, ...parsed.systems };
            }
            setSettings(merged);
          } catch (err) {
            console.error(err);
          }
        }
      } finally {
        if (!isCancelled) setLoadingSettings(false);
      }
    };

    loadSettings();

    return () => {
      isCancelled = true;
    };
  }, [userId]);

  // 2. تطبيق الثيم والقياس عند تغير الإعدادات
  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove("light", "dark");
    const activeTheme =
      settings.theme === "system"
        ? window.matchMedia("(prefers-color-scheme: dark)").matches
          ? "dark"
          : "light"
        : settings.theme;
    root.classList.add(activeTheme);
    root.style.colorScheme = activeTheme;

    // حفظ نسخة محلية خاصة بالمستخدم
    const storageKey = getStorageKey(userId);
    localStorage.setItem(storageKey, JSON.stringify(settings));
  }, [settings, userId]);

  const updateSettings = async (newSettings: Partial<AppSettings>) => {
    const updated = { ...settings, ...newSettings };
    if (newSettings.systems) {
      updated.systems = { ...settings.systems, ...newSettings.systems };
    }

    setSettings(updated);
    const storageKey = getStorageKey(userId);
    localStorage.setItem(storageKey, JSON.stringify(updated));

    // حفظ في Supabase إذا كان المستخدم مسجلاً
    if (userId && !userId.includes("undefined")) {
      try {
        await supabase
          .from("profiles")
          .update({ app_settings: updated })
          .eq("id", userId);
      } catch (e) {
        console.error("Error updating settings in Supabase:", e);
      }
    }
  };

  return (
    <SettingsContext.Provider
      value={{ settings, updateSettings, loadingSettings }}
    >
      {children}
    </SettingsContext.Provider>
  );
};

export const useSettings = () => {
  const context = useContext(SettingsContext);
  if (!context)
    throw new Error("useSettings must be used within SettingsProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback } from 'react';

export interface UIContextType {
  loading: boolean;
  setLoading: (loading: boolean) => void;
  isPhase2Loading: boolean;
  setIsPhase2Loading: (loading: boolean) => void;
  loadingMessage: string | null;
  setLoadingMessage: (message: string | null) => void;
  setLoadingState: (loading: boolean, message: string | null) => void;
  highlightedItemId: string | null;
  setHighlightedItemId: (id: string | null) => void;
  statementAction: { route: string; parentId: string } | null;
  setStatementAction: (action: { route: string; parentId: string } | null) => void;
  isOffline: boolean;
  setIsOffline: (offline: boolean) => void;
  isSyncing: boolean;
  setIsSyncing: (syncing: boolean) => void;
  presences: Record<string, any>;
  setPresences: React.Dispatch<React.SetStateAction<Record<string, any>>>;
  notifications: any[];
  setNotifications: React.Dispatch<React.SetStateAction<any[]>>;
  markNotificationAsRead: (id: string) => void;
  markAllNotificationsAsRead: () => void;
  clearNotifications: () => void;
}

const UIContext = createContext<UIContextType | undefined>(undefined);

export const UIProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [loading, setLoading] = useState(true);
  const [isPhase2Loading, setIsPhase2Loading] = useState(true);
  const [loadingMessage, setLoadingMessage] = useState<string | null>(null);
  const [highlightedItemId, setHighlightedItemId] = useState<string | null>(null);
  const [statementAction, setStatementAction] = useState<{ route: string; parentId: string } | null>(null);
  const [presences, setPresences] = useState<Record<string, any>>({});
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [notifications, setNotifications] = useState<any[]>([]);

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const setLoadingState = useCallback((l: boolean, m: string | null) => {
    setLoading(l);
    setLoadingMessage(m);
  }, []);

  const markNotificationAsRead = useCallback((id: string) => {
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n));
  }, []);

  const markAllNotificationsAsRead = useCallback(() => {
    setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
  }, []);

  const clearNotifications = useCallback(() => {
    setNotifications([]);
  }, []);

  const value: UIContextType = {
    loading,
    setLoading,
    isPhase2Loading,
    setIsPhase2Loading,
    loadingMessage,
    setLoadingMessage,
    setLoadingState,
    highlightedItemId,
    setHighlightedItemId,
    statementAction,
    setStatementAction,
    isOffline,
    setIsOffline,
    isSyncing,
    setIsSyncing,
    presences,
    setPresences,
    notifications,
    setNotifications,
    markNotificationAsRead,
    markAllNotificationsAsRead,
    clearNotifications,
  };

  return <UIContext.Provider value={value}>{children}</UIContext.Provider>;
};

export const useUI = () => {
  const context = useContext(UIContext);
  if (!context) {
    throw new Error('useUI must be used within a UIProvider');
  }
  return context;
};

