// v13: دعم الـ Sync Queue وإدارة البيانات غير المرفوعة أثناء عدم توفر الإنترنت (Offline-First)
export class AlMohasebLocalDB extends Dexie {
    invoices!: Table<Invoice>;
    invoice_price_items!: Table<InvoicePriceItem>;
    invoice_deductions!: Table<InvoiceDeductionItem>;
    expenses!: Table<Expense>;
    cycles!: Table<Cycle>;
    persons!: Table<Person>;
    advances!: Table<Advance>;
    suppliers!: Table<Supplier>;
    supplier_payments!: Table<SupplierPayment>;
    farmers!: Table<Farmer>;
    farmer_withdrawals!: Table<FarmerWithdrawal>;
    expense_categories!: Table<ExpenseCategory>;
    assets!: Table<Asset>;
    bank_accounts!: Table<BankAccount>;
    bank_transactions!: Table<BankTransaction>;
    daily_logs!: Table<DailyLog>;
    virtual_members!: Table<VirtualMember>;
    partner_debts!: Table<PartnerDebt>;
    cache!: Table<CacheEntry, string>;
    sync_queue!: Table<SyncQueueItem, number>;

    constructor() {
        super('AlMohaseb_Local_V11');
        // FIX: Casting this to any to access the version method, as inheritance may not be correctly resolved by the compiler.
        (this as any).version(11).stores({
            invoices: 'id, cycle_id, date, market',
            invoice_price_items: '++id, invoice_id',
            invoice_deductions: '++id, invoice_id',
            expenses: 'id, cycle_id, category_id, date',
            cycles: 'id, status, start_date',
            persons: 'id, name',
            advances: 'id, person_id, cycle_id, date',
            suppliers: 'id, name',
            supplier_payments: 'id, supplier_id, cycle_id, date',
            farmers: 'id, name',
            farmer_withdrawals: 'id, farmer_id, cycle_id, date',
            expense_categories: 'id, name, is_establishment',
            assets: 'id, name',
        });
        (this as any).version(12).stores({
            bank_accounts: 'id, name',
            bank_transactions: 'id, account_id, date',
            daily_logs: 'id, date',
            virtual_members: 'id, owner_id',
            partner_debts: 'id, partner_id',
            cache: 'key'
        });
        (this as any).version(13).stores({
            sync_queue: '++id, table, action, created_at'
        });
    }
}

export const db = new AlMohasebLocalDB();

export const hardResetLocalDB = async () => {
    try {
        // FIX: Casting db to any to access the Dexie instance method delete().
        await (db as any).delete();
        window.localStorage.clear();
        const dbs = await window.indexedDB.databases();
        for (const database of dbs) {
            if (database.name && database.name.includes('AlMohaseb')) {
                window.indexedDB.deleteDatabase(database.name);
            }
        }
    } catch (e) {
        console.error("Reset failed", e);
    } finally {
        window.location.href = '/';
    }
};

import { LocalNotifications } from '@capacitor/local-notifications';
import { PushNotifications } from '@capacitor/push-notifications';
import { Capacitor } from '@capacitor/core';
import { supabase } from './supabase';

export async function requestNotificationPermissions() {
  if (!Capacitor.isNativePlatform()) return false;

  try {
    let status = await LocalNotifications.checkPermissions();
    if (status.display === 'prompt') {
      status = await LocalNotifications.requestPermissions();
    }

    // Also request push notification permissions
    let pushStatus = await PushNotifications.checkPermissions();
    if (pushStatus.receive === 'prompt') {
      pushStatus = await PushNotifications.requestPermissions();
    }

    return status.display === 'granted' || pushStatus.receive === 'granted';
  } catch (error) {
    console.error('Error requesting notification permissions:', error);
    return false;
  }
}

export async function registerForPushNotifications(profileId: string | undefined) {
  if (!Capacitor.isNativePlatform() || !profileId) return;

  try {
    const hasPermission = await requestNotificationPermissions();
    if (!hasPermission) return;

    // Remove old listeners to prevent duplicates on multiple calls
    await PushNotifications.removeAllListeners();

    // On success, we should be able to receive notifications
    PushNotifications.addListener('registration', async (token) => {
      console.log('Push registration success, token: ' + token.value);

      try {
        // Check if the current user is a virtual member (employee)
        if (profileId.includes('virtual_')) {
          const dbId = profileId.replace(/virtual_/g, '');
          const { error } = await supabase
            .from('virtual_members')
            .update({ push_token: token.value })
            .eq('id', dbId);

          if (error) {
              console.error('Failed to update push token for virtual member:', error);
          } else {
              console.log('Push token saved successfully for virtual member:', dbId);
          }
        } else {
            // Save for main owner profile
            const { error } = await supabase
              .from('profiles')
              .update({ push_token: token.value })
              .eq('id', profileId);

            if (error) {
                 console.error('Failed to update push token for owner profile:', error);
            } else {
                 console.log('Push token saved successfully for owner:', profileId);
            }
        }
      } catch (err) {
        console.error('Error saving push token:', err);
      }
    });

    // Some issue with our setup and push will not work
    PushNotifications.addListener('registrationError', (error: any) => {
      console.error('Error on registration: ' + JSON.stringify(error));
    });

    // Show us the notification payload if the app is open on our device
    PushNotifications.addListener('pushNotificationReceived', (notification) => {
      console.log('Push received: ' + JSON.stringify(notification));

      // Re-trigger it locally so the user sees it even if in-app
      sendLocalNotification(notification.title || 'إشعار جديد', notification.body || '', notification.data);
    });

    // Method called when tapping on a push notification
    PushNotifications.addListener('pushNotificationActionPerformed', (notification) => {
      console.log('Push action performed: ' + JSON.stringify(notification));
      const data = notification.notification.data;
      if (data && data.route) {
        window.dispatchEvent(new CustomEvent('notificationInteraction', { 
            detail: { route: data.route, itemId: data.itemId, parentId: data.parentId } 
        }));
      }
    });

    // Method called when tapping on a local notification
    LocalNotifications.addListener('localNotificationActionPerformed', (notification) => {
        console.log('Local action performed: ' + JSON.stringify(notification));
        const data = notification.notification.extra;
        if (data && data.route) {
          window.dispatchEvent(new CustomEvent('notificationInteraction', { 
              detail: { route: data.route, itemId: data.itemId, parentId: data.parentId } 
          }));
        }
    });

    // Register with Apple / Google to receive push via APNS/FCM
    // MUST BE CALLED AFTER ADDING LISTENERS
    await PushNotifications.register();

    // Create a high-priority channel for Android to force Heads-Up (Banner) notifications
    if (Capacitor.getPlatform() === 'android') {
      try {
        await PushNotifications.createChannel({
          id: 'high_priority_notifications',
          name: 'High Priority Alerts',
          description: 'Critical alerts for accounting system',
          importance: 5, // 5 = HIGH IMPORTANCE (heads up popup)
          visibility: 1, // 1 = PUBLIC
          vibration: true,
        });
      } catch (channelError) {
        console.error('Failed to create notification channel:', channelError);
      }
    }

  } catch (error) {
    console.error('Push notification registration failed:', error);
  }
}

export async function sendLocalNotification(title: string, body: string, data: any = {}) {
  if (!Capacitor.isNativePlatform()) {
    console.log('Notification (Web):', title, body);
    return;
  }

  try {
    const hasPermission = await requestNotificationPermissions();
    if (!hasPermission) return;

    await LocalNotifications.schedule({
      notifications: [
        {
          title,
          body,
          id: Math.floor(Math.random() * 1000000),
          schedule: { at: new Date(Date.now() + 1000) }, // Send after 1 second
          extra: data,
          sound: undefined,
          actionTypeId: '',
          attachments: []
        }
      ]
    });
  } catch (error) {
    console.error('Error sending local notification:', error);
  }
}

/**
 * Whitelist payload formatting for Supabase database operations.
 * Ensures only explicitly allowed columns are sent to Supabase tables,
 * preventing extra computed fields or runtime metadata from breaking updates.
 */

// Invoices table
export interface DbInvoicePayload {
    id?: string;
    user_id?: string;
    description?: string;
    date: string;
    cycle_id: string;
    market: string;
    packaging_type: 'carton' | 'cage';
    packaging_count?: number;
    carton_count?: number;
    cage_count?: number;
    created_at?: string;
}

export const sanitizeInvoicePayload = (obj: any): Partial<DbInvoicePayload> => {
    if (!obj || typeof obj !== 'object') return {};
    const allowedKeys: (keyof DbInvoicePayload)[] = [
        'id', 'user_id', 'description', 'date', 'cycle_id', 'market',
        'packaging_type', 'packaging_count', 'carton_count', 'cage_count', 'created_at'
    ];
    const clean: any = {};
    for (const key of allowedKeys) {
        if (key in obj && obj[key] !== undefined) {
            clean[key] = obj[key];
        }
    }
    return clean;
};

